import { Ratelimit } from '@upstash/ratelimit'
import { Redis } from '@upstash/redis'

/**
 * Upstash Redis rate limiters — three tiers.
 * In dev without UPSTASH_REDIS_REST_URL/TOKEN, returns a no-op stub that always allows.
 */

type Limiter = {
  limit: (identifier: string) => Promise<{
    success: boolean
    limit: number
    remaining: number
    reset: number
  }>
}

const hasUpstash = Boolean(
  process.env.UPSTASH_REDIS_REST_URL && process.env.UPSTASH_REDIS_REST_TOKEN
)

const noop: Limiter = {
  async limit() {
    return { success: true, limit: 9999, remaining: 9999, reset: Date.now() + 60_000 }
  },
}

function make(prefix: string, requests: number, window: `${number} ${'s' | 'm'}`): Limiter {
  if (!hasUpstash) return noop
  return new Ratelimit({
    redis: Redis.fromEnv(),
    limiter: Ratelimit.slidingWindow(requests, window),
    analytics: true,
    prefix,
  })
}

export const apiRatelimit = make('rl:api', 10, '10 s')
export const authedRatelimit = make('rl:auth', 60, '1 m')
export const expensiveRatelimit = make('rl:exp', 5, '1 m')
export const loginRatelimit = make('rl:auth:login', 5, '60 s')
export const signupRatelimit = make('rl:auth:signup', 3, '60 s')
export const forgotPasswordRatelimit = make('rl:auth:forgot', 2, '60 s')

import { createServerClient } from '@supabase/ssr'
import { cookies } from 'next/headers'
import { cache } from 'react'
import type { Database } from './types'

type StudioRole = Database['public']['Tables']['studio_members']['Row']['role']

export interface AuthenticatedUser {
  user: Database['public']['Tables']['profiles']['Row'] & { authId: string }
  studioId: string
  role: StudioRole
}


/**
 * Server Supabase client for Server Components, API Route Handlers, and Server Actions.
 *
 * Uses the anon key + user session cookies.
 * RLS policies apply based on the authenticated user.
 *
 * IMPORTANT: cookies() is async in Next.js 16 — must be awaited.
 */
export async function createClient() {
  const cookieStore = await cookies()

  return createServerClient<Database>(
    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!,
    {
      cookies: {
        getAll() {
          return cookieStore.getAll()
        },
        setAll(cookiesToSet) {
          try {
            cookiesToSet.forEach(({ name, value, options }) =>
              cookieStore.set(name, value, options)
            )
          } catch {
            // setAll called from a Server Component — cookies cannot be set
            // middleware handles session refresh
          }
        },
      },
    }
  )
}

/**
 * Cached helper that validates the session and returns the authenticated user
 * together with their primary studio context.
 *
 * Wrapped in React cache() so repeated calls within the same render tree
 * (e.g. layout + page) are deduplicated — only one round-trip per request.
 *
 * Returns null when the user is not authenticated or has no studio membership.
 */
export const getAuthenticatedUser = cache(async (): Promise<AuthenticatedUser | null> => {
  const supabase = await createClient()
  const { data: { user }, error: authError } = await supabase.auth.getUser()

  if (authError || !user) return null

  const [profileResult, memberResult] = await Promise.all([
    supabase
      .from('profiles')
      .select('id, email, full_name, avatar_url, is_platform_admin, created_at, updated_at')
      .eq('id', user.id)
      .single(),
    supabase
      .from('studio_members')
      .select('studio_id, role')
      .eq('user_id', user.id)
      .order('created_at', { ascending: true })
      .limit(1)
      .single(),
  ])

  if (profileResult.error || !profileResult.data) return null
  if (memberResult.error || !memberResult.data) return null

  return {
    user: { ...profileResult.data, authId: user.id },
    studioId: memberResult.data.studio_id,
    role: memberResult.data.role,
  }
})

/**
 * Service-role Supabase client for webhook handlers and admin operations.
 *
 * Bypasses RLS. NEVER expose to client. Only use server-side.
 */
export function createServiceRoleClient() {
  const serviceRoleKey = process.env.SUPABASE_SERVICE_ROLE_KEY
  if (!serviceRoleKey) {
    throw new Error('SUPABASE_SERVICE_ROLE_KEY is not set')
  }

  return createServerClient<Database>(
    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    serviceRoleKey,
    {
      cookies: {
        getAll() {
          return []
        },
        setAll() {
          // No-op for service role — no session cookies
        },
      },
      auth: {
        autoRefreshToken: false,
        persistSession: false,
      },
    }
  )
}
import { type ClassValue, clsx } from 'clsx'
import { twMerge } from 'tailwind-merge'

/**
 * Merge Tailwind CSS class names without conflicts.
 */
export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs))
}

/**
 * Format a currency amount from cents to a display string.
 */
export function formatCurrency(cents: number, currency = 'USD', locale = 'en-US'): string {
  return new Intl.NumberFormat(locale, {
    style: 'currency',
    currency,
    minimumFractionDigits: 0,
    maximumFractionDigits: 2,
  }).format(cents / 100)
}

/**
 * Format a date for display.
 */
export function formatDate(date: Date | string, options?: Intl.DateTimeFormatOptions): string {
  const d = typeof date === 'string' ? new Date(date) : date
  return new Intl.DateTimeFormat('en-US', {
    year: 'numeric',
    month: 'short',
    day: 'numeric',
    ...options,
  }).format(d)
}

/**
 * Generate a URL-safe slug from a string.
 */
export function slugify(input: string): string {
  return input
    .toLowerCase()
    .trim()
    .replace(/[^\w\s-]/g, '')
    .replace(/[\s_-]+/g, '-')
    .replace(/^-+|-+$/g, '')
}

/**
 * Truncate a string to a maximum length with an ellipsis.
 */
export function truncate(str: string, maxLength: number): string {
  if (str.length <= maxLength) return str
  return `${str.slice(0, maxLength - 3)}...`
}

/**
 * Type guard to check if a value is a non-null object.
 */
export function isObject(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value)
}

