/**
 * Centralized query key factory.
 *
 * All TanStack Query keys are defined here to prevent typos,
 * enable precise invalidation, and provide IntelliSense.
 */

export const queryKeys = {
  dashboard: {
    all: () => ['dashboard'] as const,
    // studioId omitted — API routes derive studio from the authenticated session
    kpis: () => [...queryKeys.dashboard.all(), 'kpis'] as const,
    schedule: (date: string) => [...queryKeys.dashboard.all(), 'schedule', date] as const,
    activity: () => [...queryKeys.dashboard.all(), 'activity'] as const,
    alerts: () => [...queryKeys.dashboard.all(), 'alerts'] as const,
  },
  studios: {
