    detail: (studioId: string) => [...queryKeys.studios.all(), studioId] as const,
    members: (studioId: string) => [...queryKeys.studios.detail(studioId), 'members'] as const,
    locations: (studioId: string) =>
      [...queryKeys.studios.detail(studioId), 'locations'] as const,
  },
  appointments: {
