} as const
import { QueryClient } from '@tanstack/react-query'

/**
 * Creates a new QueryClient with production-ready defaults.
 *
 * Used in QueryProvider to create per-request client on the server
 * and a singleton client on the browser.
 */
export function makeQueryClient(): QueryClient {
  return new QueryClient({
    defaultOptions: {
      queries: {
        // Data is considered fresh for 60 seconds by default
        staleTime: 60_000,
        // Retry once on failure (default 3 is too aggressive)
        retry: 1,
        // Don't refetch on window focus in dev (annoying)
        refetchOnWindowFocus: process.env.NODE_ENV === 'production',
      },
      mutations: {
        retry: 0,
      },
    },
  })
}

let browserQueryClient: QueryClient | undefined

/**
 * Returns the singleton QueryClient for browser usage.
 * Creates it on first call. Safe to call in Client Components.
 */
export function getQueryClient(): QueryClient {
  if (typeof window === 'undefined') {
    // Server: always make a new client (prevents cross-request state sharing)
    return makeQueryClient()
  }
  // Browser: reuse the same client across renders
  browserQueryClient ??= makeQueryClient()
  return browserQueryClient
